def transform(grid):
    h, w = len(grid), len(grid[0])
    # The task's distinctive color is the non-background color; background
    # values in these puzzles are 0 and one other color.
    colors = {v for row in grid for v in row if v not in (0, 3, 5, 7)}
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    sh, sw = r1-r0+1, c1-c0+1
    out = [row[:] for row in grid]
    for y in range(h-sh+1):
        for x in range(w-sw+1):
            if all(grid[y+dr][x+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[y+dr][x+dc] = color
    return out
